## Analysis

The problem is in how `AppIcon.vue` updates the project. When the project changes, it calls `$ui.showApp()` with updated params, but this creates a **new app entry** or updates the store. However, other components connected to the same app instance are watching `this.$app` (from globalMixin), which reads from `$ui.openApps[tabId]`.

The issue is that `showApp` in `ui.js` uses spread to create a new object:
```js
state.openApps = { ...state.openApps, [app.tabId]: app }
```

But the `app` passed has a **new params** object. The components using `this.$app` should reactively pick up the change since they compute from `$ui.openApps[tabId]`.

Let me trace the problem more carefully:

1. `AppIcon` watches `project`, calls `$ui.showApp({ ...this.app, params: { ...this.app.params, project_id: ... } })`
2. `showApp` mutation updates `openApps` with the new app object
3. `$app` computed in globalMixin returns `this.$ui.openApps[tabId]`
4. `tabId` comes from `this.$props.params?.params?.app?.tabId` - this is the **original** params passed at panel creation

The fix: `AppIcon` should **mutate the app in place** in the store rather than creating a new app. Also, the `$projectId` computed needs to properly react to changes. Let me fix both `AppIcon.vue` and `ui.js`:

```js client/src/store/ui.js
import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'
import { API } from '../api/api'
import moment from 'moment'

export const namespaced = true

export const state = () => ({
  showCoder: false,
  showBrowser: false,
  lastActiveTab: "",
  codxJuniorWidth: 30,
  isMobile: false,
  orientation: 'portrait',
  openedFile: null,
  showLogs: false,
  voiceLanguage: 'en-US',
  voiceLanguages: {
    "en-US": "English",
    "es-SP": "Español"
  },
  openApps: {},
  appDivided: 'horizontal',
  resolution: API.screen.display?.resolution,
  resolutions: API.screen.display?.resolutions,
  monitor: "preview",
  monitors: {
    "preview": "CODX-SCREEN-PREVIEW",
    "shared": "CODX-SCREEN-SHARED"
  },
  colorsMap: {},
  coderProjectCodxPath: null,
  uiReady: false,
  floatingCodxJunior: false,
  notifications: [],
  noVNCSettings: {
    resize: 'remote',
  },
  theme: 'dark',
  activeTab: 'home',
  newProject: false,
  activeApp: null,
  appShowMode: null
})

export const getters = getterTree(state, {
  isLandscape: state => state.orientation !== 'portrait',
  monitorToken: state => state.monitors[state.monitor],
  isSharedScreen: () => window.location.pathname === '/shared',
  enableFileManger: () => API.globalSettings?.enable_file_manager,
  activeApps: () => Object.values($storex.ui.openApps)
})

export const mutations = mutationTree(state, {
  setActiveTab(state, tab) {
    tab = tab || 'home'
    if (state.activeTab === tab) {
      if (state.activeApp) {
        state.activeTab = null
      }
    } else {
      state.activeTab = tab
    }
    $storex.ui.showApp({
      name: tab,
      component: tab
    })
    $storex.ui.saveState()
  },
  showTab(state, tab) {
    if (tab !== state.activeTab) {
      $storex.ui.setActiveTab(tab)
    }
    if (!state.isMobile) {
      $storex.ui.showApp({
        name: tab,
        component: tab
      })
    }
  },
  closeTab(state) {
    state.activeTab = null
  },
  setCodxJuniorWidth(state, width) {
    state.codxJuniorWidth = width
    $storex.ui.saveState()
  },
  toggleLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.showApp({
      name: 'Logs',
      component: 'log-viewer'
    })
  },
  setVoiceLanguage(state, voiceLanguage) {
    state.voiceLanguage = voiceLanguage
    $storex.ui.saveState()
  },
  setAppDivided(state, divided) {
    state.appDivided = divided
    $storex.ui.saveState()
  },
  setMonitor(state, monitor) {
    state.monitor = monitor
    $storex.ui.saveState()
  },
  setColorsMap(state, colorsMap) {
    state.colorsMap = colorsMap
    $storex.ui.saveState()
  },
  coderOpenPath(state, project) {
    state.coderProjectCodxPath = project.codx_path
  },
  setUIready(state) {
    $storex.ui.loadState()
    state.uiReady = true
  },
  setFloatinCodxJunior(state, floating) {
    state.floatingCodxJunior = floating
    $storex.ui.saveState()
  },
  toggleFloatinCodxJunior(state) {
    state.floatingCodxJunior = !state.floatingCodxJunior
    $storex.ui.saveState()
  },
  addNotification(state, { text, type }) {
    const existing = state.notifications?.find(n => n.text === text)
    if (existing) {
      existing.ts = moment().format("hh:mm:ss")
      return
    }
    const notif = {
      ts: moment().format("hh:mm:ss"),
      text,
      type
    }
    state.notifications.push(notif)
    setTimeout(() => $storex.ui.removeNotification(notif), 30000)
  },
  removeNotification(state, notification) {
    state.notifications.splice(
      state.notifications.findIndex(n => n === notification), 1)
  },
  setNoVNCSettings(state, settings) {
    state.noVNCSettings = { ...state.noVNCSettings, ...settings }
  },
  setTheme(state, theme) {
    state.theme = theme
  },
  showNewProject(state, show) {
    state.newProject = show
  },
  cloneApp(state, app) {
    $storex.ui.showApp({ ...app, tabId: null })
  },
  showApp(state, app) {
    app.tabId = app.tabId || `${app.key || app.name}-${(new Date().getTime())}`
    app.params = app.params || {}
    state.openApps = {
      ...state.openApps,
      [app.tabId]: app
    }
  },
  // Update params of an existing app without creating a new tab
  updateAppParams(state, { tabId, params }) {
    const app = state.openApps[tabId]
    if (!app) return
    // Replace entire openApps to trigger Vue reactivity
    state.openApps = {
      ...state.openApps,
      [tabId]: {
        ...app,
        params: {
          ...app.params,
          ...params
        }
      }
    }
  },
  closeApp(state, app) {
    if (!app) return
    delete state.openApps[app.tabId]
    if (state.activeApp?.tabId === app.tabId) {
      state.activeApp = state.openApps[Object.keys(state.openApps).reverse()[0]]
    }
    if (!Object.keys(state.openApps).length) {
      if (!state.activeTab) {
        $storex.ui.showTab(state.lastActiveTab || 'home')
      }
    }
    $storex.ui.saveState()
  },
  setAppShowMode(state, mode) {
    state.appShowMode = mode
  },
  openChat(state, chat) {
    $storex.ui.showApp({
      name: chat.name,
      component: 'chat',
      params: {
        chat: {
          id: chat.id,
          name: chat.name,
          owner_project_id: chat.owner_project_id
        }
      }
    })
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init ({ state }, $storex) {
      $storex.ui.handleResize()
      window.addEventListener('resize', () => $storex.ui.handleResize())
      state.activeApp = "home"
      if (API.user?.theme) {
        state.theme = API.user.theme
      }
      state.coderProjectCodxPath = null
    },
    saveState({ state }) {
      if (!state.uiReady) {
        return
      }
      const data = { 
        ...state, 
        uiReady: false,
        activeApp: null,
        openApps: {}  // Stored in layouts
      }
      localStorage.setItem('uiState', JSON.stringify(data))
    },
    async loadState({ state }) {
      const savedState = localStorage.getItem('uiState')
      if (savedState) {
        const parsedState = JSON.parse(savedState)
        Object.keys(parsedState)
          .forEach(k => state[k] = parsedState[k])
      }
      const {
        activeProject: project_id,
        activeChat: chatId
      } = state

      if (project_id && project_id !== $storex.projects.activeProject?.project_id) {
        await $storex.projects.setActiveProject({ project_id })
      }
      if (chatId && $storex.projects.activeProject) {
        $storex.projects.setActiveChat({ id: chatId })
      }
      state.activeApp = Object.values(state.openApps)[0]

      $storex.ui.handleResize()
    },
    handleResize({ state }) {
      const width = window.innerWidth
      const height = window.innerHeight
      const isMobile = width <= 1024
      const orientation = width > height ? 'landscape' : 'portrait'
      state.isMobile = isMobile
      state.orientation = orientation  
    },
    loadTask (_, task) {
      $storex.projects.setActiveChat(task)
    },
    async openFile({ state }, file) {
      if (state.isMobile) {
        state.openedFile = file
      } else {
        await API.coder.openFile(file)
      }
      state.showCoder = true
    },
    async openProjectFile({ state }, file) {
      const { project_path } = $storex.projects.activeProject
      if (!file.startsWith(project_path)) {
        if (!file.startsWith("/") && !project_path.endsWith("/")) {
          file = "/" + file
        }
        file = project_path + file
      }
      await API.coder.openFile(file)
      state.showCoder = true
    },
    setScreenResolution(_, resolution) {
      API.screen.setScreenResolution(resolution)
    },
    async readScreenResolutions ({ state }) {
      await API.screen.getScreenResolution()
      state.resolution = API.screen.display?.resolution
      state.resolutions = API.screen.display?.resolutions
    },
    copyTextToClipboard(_, text) {
      const textArea = document.createElement('textarea')
      textArea.value = text
      document.body.appendChild(textArea)
      textArea.focus()
      textArea.select()
      document.execCommand('copy')
      document.body.removeChild(textArea)
      $storex.ui.addNotification({ text: "Text copied" })
    },
    async readClipboardText(_, itemType = "text/plain") {
      const items = await navigator.clipboard.read()
      const getText = async item => {
        const blob = await item.getType(itemType)
        return await blob.text()
      }
      const allTexts = await Promise.all(
                        items.filter(i => i.types.includes(itemType))
                              .map(i => getText(i)))
      return allTexts.reduce((a, b) => a + b, "")
    },
    async shareScreen() {
      const stream = await navigator.mediaDevices.getDisplayMedia({
        preferCurrentTab: true,
      })
      const [track] = stream.getVideoTracks()
    },
    openNewWindowAppPanel(_, app) {
      const { origin } = window.location
      const url = `${origin}${app.path}`
      window.open(url, app.name)
    }
  },
)
```

Now fix `AppIcon.vue` to use `updateAppParams` instead of `showApp`, and fix `main.ts` to make `$project` and `$projectId` properly reactive from the store:

```vue client/src/components/apps/AppIcon.vue
<script setup>
import { 
  MenubarRoot,
  MenubarMenu,
  MenubarTrigger,
  MenubarPortal,
  MenubarContent,
} from 'reka-ui'
import MenubarItem from '../main-menu/MenubarItem.vue'
import MenuDivider from '../main-menu/MenuDivider.vue'
import ProjectDetailt from '../ProjectDetailt.vue'
</script>

<template>
  <MenubarRoot>
    <MenubarMenu>
      <MenubarTrigger class="MenubarTrigger click">
        <div class="flex items-center gap-2">
          <img
            class="w-5 rounded-full"
            :src="currentProject?.project_icon"
            v-if="currentProject && currentProject !== $project"
          />
          <i class="fa-solid fa-bars mx-1" v-else></i>
        </div>
      </MenubarTrigger>
      <MenubarPortal>
        <MenubarContent
          class="outline-none bg-base-100 rounded-lg p-[5px] border border-white/30 shadow-sm [animation-duration:_400ms] [animation-timing-function:_cubic-bezier(0.16,_1,_0.3,_1)] will-change-[transform,opacity]"
        >
          <MenubarItem>
            <!-- Stop click propagation so menu doesn't close on project change -->
            <ProjectDetailt @click.stop="" v-model="currentProject" @change="" />
          </MenubarItem>
          <MenuDivider />
          <MenubarItem @click.stop="$ui.cloneApp(app)">
            Duplicate
          </MenubarItem>
          <MenubarItem @click.stop="$ui.openNewWindowAppPanel(app)" v-if="app.path">
            New window <i class="fa-solid fa-arrow-up-right-from-square"></i>
          </MenubarItem>
        </MenubarContent>
      </MenubarPortal>
    </MenubarMenu>
  </MenubarRoot>
</template>

<script>
export default {
  props: ['app', 'iconClass'],
  data() {
    return {
      imageOk: false,
      imageError: false,
    }
  },
  computed: {
    // Read project_id from the live store app, not from the prop
    // This ensures reactivity when updateAppParams is called
    liveApp() {
      return this.$ui.openApps[this.app?.tabId] || this.app
    },
    currentProjectId() {
      return this.liveApp?.params?.project_id
    },
    currentProject: {
      get() {
        return this.$projects.allProjectsById[this.currentProjectId] || this.$project
      },
      set(project) {
        if (!project || project.project_id === this.currentProjectId) return
        // Update the app params in the store so all components react
        this.$ui.updateAppParams({
          tabId: this.app.tabId,
          params: { project_id: project.project_id }
        })
      }
    },
    awesomeIcon() {
      if (this.app.icon?.includes("fa"))
        return this.app.icon + " fa-sm"
      return null
    },
    imageUrl() {
      if (this.imageError) return null
      if (this.app.icon?.startsWith('http')) return this.app.icon
      const path = this.app.path?.split("#")[0]
      if (path) {
        const sep = this.app.path?.endsWith("/") ? "" : "/"
        return `${path}${sep}favicon.ico`
      }
      return null
    }
  }
}
</script>
```

Now update `globalMixin` in `main.ts` so `$project` and `$projectId` react to store changes:

```js client/src/main.ts
import './assets/main.css'

import { createApp, onBeforeMount, onBeforeUnmount, watch } from 'vue'
import store, { $storex } from "./store"
import service from "./service"

import App from './App.vue'
import Modal from './components/Modal.vue'
import router from './router'
import Markdown from '@/components/Markdown.vue'

import 'vuefinder/dist/style.css'
import VueFinder from 'vuefinder/dist/vuefinder'

// BUG: error loading module. Keep it here
import highlightjs from 'highlight.js'

// Monaco editor
import editorWorker from 'monaco-editor/esm/vs/editor/editor.worker?worker'
import jsonWorker from 'monaco-editor/esm/vs/language/json/json.worker?worker'
import cssWorker from 'monaco-editor/esm/vs/language/css/css.worker?worker'
import htmlWorker from 'monaco-editor/esm/vs/language/html/html.worker?worker'
import tsWorker from 'monaco-editor/esm/vs/language/typescript/ts.worker?worker'

self.MonacoEnvironment = {
  getWorker(_, label) {
    if (label === 'json') {
      return new jsonWorker()
    }
    if (label === 'css' || label === 'scss' || label === 'less') {
      return new cssWorker()
    }
    if (label === 'html' || label === 'handlebars' || label === 'razor') {
      return new htmlWorker()
    }
    if (label === 'typescript' || label === 'javascript') {
      return new tsWorker()
    }
    return new editorWorker()
  },
}

function generateUID(length) {
  return window.btoa(String.fromCharCode(...window.crypto.getRandomValues(new Uint8Array(length * 2)))).replace(/[+/=]/g, "").substring(0, length)
}

const globalMixin = {
  onBeforeMount() {
    console.log("Before mount. Events: ", this.events, this.$root)
  },
  onBeforeUnmount() {
    console.log("Before Unmount. Events: ", this.events)
  },
  computed: {
    $storex () {
      return $storex
    },
    $ui () {
      return $storex.ui
    },
    $projects () {
      return $storex.projects
    },
    // $app reads from live store so it reacts to updateAppParams
    $app () {
      const tabId = this.$props?.params?.params?.app?.tabId
      if (!tabId) return null
      return $storex.ui.openApps[tabId]
    },
    // $projectId derived from live $app so it updates when params change
    $projectId() {
      return this.$app?.params?.project_id ||
             this.$props?.params?.params?.app?.params?.project_id
    },
    // $project resolves from live projectId for full reactivity
    $project () {
      return $storex.projects.allProjectsById[this.$projectId] ||
             $storex.projects.activeProject
    },
    $session () {
      return $storex.session
    },
    $user () {
      return $storex.api.user
    },
    $users () {
      return $storex.users
    },
    $chats () {
      return $storex.chats
    },
    $globalSettings() {
      return $storex.api.globalSettings
    },
    $service () {
      return service
    },
  },
  watch: {
    params: {
      handler(newValue, oldValue) {
        if (newValue) {
          console.log("Component params changed", {newValue, oldValue})
        }
      },
      immediate: true
    }
  },
  methods: {
    $bubble(event: string, data: EventInit) {
    },
    generateUID
  }
}

$storex.users.login()

const app = createApp(App)
              .mixin(globalMixin)
              .use(store)
              .use(router)
              .use(VueFinder)
              .component('modal', Modal)
              .component('Markdown', Markdown)
              .mount('#app')

$storex.app = app
$storex.$router = router

// eruda for mobile debugging
window.setTimeout(() =>
  (function() {
    function isMobile() {
      return /Mobi|Android/i.test(navigator.userAgent)
    }
    if (isMobile()) {
      var script1 = document.createElement('script')
      script1.src = "https://cdn.jsdelivr.net/npm/eruda"
      document.body.appendChild(script1)
    }
  })(), 10)
